<?php require_once 'includes/auth.php';require_login();verify_csrf();$cur=$_POST['current']??'';$new=$_POST['new_password']??'';$con=$_POST['confirm']??'';$s=mysqli_prepare($conn,"SELECT password FROM users WHERE id=?");$id=user()['id'];mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$r||!password_verify($cur,$r['password']))redirect('profile.php?error=Current+password+is+incorrect');if(strlen($new)<8||$new!==$con)redirect('profile.php?error=New+passwords+do+not+match');$hash=password_hash($new,PASSWORD_DEFAULT);$s=mysqli_prepare($conn,"UPDATE users SET password=? WHERE id=?");mysqli_stmt_bind_param($s,'si',$hash,$id);mysqli_stmt_execute($s);log_activity('updated','profile','Changed password');redirect('profile.php?msg=Password+updated');
